def grade(ex: Exercise, answer) -> bool:
    sol = ex.solution or {}
    try:
        if ex.kind == "mcq":
            return isinstance(answer, int) and not isinstance(answer, bool) and answer == sol.get("index")
        if ex.kind == "fill":
            return isinstance(answer, str) and len(answer) <= 200 and _norm(answer) in {_norm(a) for a in sol.get("accepted", [])}
        if ex.kind == "order":
            n = len(ex.data.get("lines", []))
            if not isinstance(answer, list) or len(answer) != n or not all(isinstance(i, int) for i in answer):
                return False
            return answer in sol.get("alternatives", [list(range(n))])
        if ex.kind == "code":
            if not isinstance(answer, str) or len(answer) > 2000:
                return False
            return _patterns_ok(answer, sol.get("patterns", []), sol.get("forbid", []))
        if ex.kind == "run":
            return _grade_run(ex, answer)
    except TimeoutError:
        return False
    return False

def finish(db: Session, entry: ContestEntry, contest: Contest, user: User, now: datetime | None = None) -> list[str]:
    """Close a run (on request or when its time is up) and award XP once. Returns new badges."""
    if entry.finished_at is not None:
        return []
    now = now or datetime.now(timezone.utc)
    end = min(now, deadline(entry, contest))
    entry.finished_at = end
    entry.time_ms = int((end - gamification.aware(entry.started_at)).total_seconds() * 1000)
    entry.score = sum(1 for v in entry.results.values() if v)
    entry.xp_awarded = entry.score * XP_PER_CORRECT + (PERFECT_BONUS if entry.score == len(contest.exercise_ids) else 0)
    gamification.award_xp(db, user, entry.xp_awarded, "contest")
    earned: list[str] = []
    gamification.grant_badge(db, user, "contender", earned)
    return earned

def ranking(db: Session, contest: Contest) -> list[tuple[ContestEntry, User]]:
    """Finished runs first (score desc, then time asc), then runs still in progress (live score)."""
    rows = db.execute(
        select(ContestEntry, User).join(User, User.id == ContestEntry.user_id).where(ContestEntry.contest_id == contest.id, User.is_active.is_(True))
    ).all()

    def key(row):
        e = row[0]
        live = sum(1 for v in e.results.values() if v)
        return (e.finished_at is None, -(e.score if e.finished_at else live), e.time_ms if e.finished_at else 0, e.id)

    return sorted(rows, key=key)

export function compileTs(ts, libs, source) {
  const files = { ...libs, "runner.d.ts": RUNNER_DTS };
  let js = "";
  const strip = (n) => n.replace(/^\/+/, "");
  const host = {
    getSourceFile(name, languageVersion) {
      name = strip(name);
      if (name === FILE) return ts.createSourceFile(FILE, source, languageVersion, true);
      if (!(name in files)) return undefined;
      if (!cache.has(name)) cache.set(name, ts.createSourceFile(name, files[name], languageVersion, true));
      return cache.get(name);
    },
    writeFile(name, text) {
      if (name.endsWith(".js")) js = text;
    },
    getDefaultLibFileName: () => ROOT_LIB,
    useCaseSensitiveFileNames: () => true,
    getCanonicalFileName: (n) => n,
    getCurrentDirectory: () => "",
    getNewLine: () => "\n",
    fileExists: (n) => strip(n) === FILE || strip(n) in files,
    readFile: (n) => (strip(n) === FILE ? source : files[strip(n)]),
    directoryExists: () => true,
    getDirectories: () => [],
  };
  const program = ts.createProgram([FILE, ...Object.keys(files)], options(ts), host);
  const main = program.getSourceFile(FILE);
  const diags = [...program.getSyntacticDiagnostics(main), ...program.getSemanticDiagnostics(main)];
  if (diags.length) {
    return {
      errors: diags.slice(0, 5).map((d) => {
        const msg = ts.flattenDiagnosticMessageText(d.messageText, "\n");
        if (d.file && d.start !== undefined) return `Line ${d.file.getLineAndCharacterOfPosition(d.start).line + 1}: ${msg}`;
        return msg;
      }),
    };
  }
  program.emit(main);
  // a file with import/export would emit module syntax the runner can't execute
  if (/^\s*(import|export)\s/m.test(js)) return { errors: ["import/export aren't available here - keep everything in one file."] };
  return { js };
}

export function proxy(request) {
  const nonce = Buffer.from(crypto.randomUUID()).toString("base64");
  const isDev = process.env.NODE_ENV === "development";

  const csp = [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${isDev ? " 'unsafe-eval'" : ""}`,
    // Inline style attributes are needed by charts/animations; styles can't execute code.
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: blob: https://lh3.googleusercontent.com",
    "font-src 'self'",
    `connect-src 'self'${isDev ? " ws:" : ""}`,
    // code runners (see lib/runners.js) - each worker script carries its own stricter CSP
    "worker-src 'self'",
    // HTML/CSS exercises: sandboxed, script-less preview frames built from srcdoc
    "frame-src 'self'",
    "object-src 'none'",
    "base-uri 'none'",
    "form-action 'self' https://accounts.google.com",
    "frame-ancestors 'none'",
    ...(isDev ? [] : ["upgrade-insecure-requests"]),
  ].join("; ");

  const requestHeaders = new Headers(request.headers);
  requestHeaders.set("x-nonce", nonce);
  requestHeaders.set("Content-Security-Policy", csp);

  const response = NextResponse.next({ request: { headers: requestHeaders } });
  response.headers.set("Content-Security-Policy", csp);
  if (!isDev) response.headers.set("Strict-Transport-Security", "max-age=63072000; includeSubDomains; preload");
  return response;
}
